module.exports = function withIosDeploymentTargetFix(config) {
  const { withPodfile } = require('expo/config-plugins');
  return withPodfile(config, (config) => {
    const hook = `
  # --- generated by withIosDeploymentTargetFix ---
  installer.pods_project.targets.each do |target|
    target.build_configurations.each do |bc|
      current = bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
      if current && Gem::Version.new(current) < Gem::Version.new('15.1')
        bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '15.1'
      end
    end
  end
  # --- end withIosDeploymentTargetFix ---`;
    const marker = 'post_install do |installer|';
    if (!config.modResults.contents.includes('withIosDeploymentTargetFix')) {
      config.modResults.contents = config.modResults.contents.replace(
        marker,
        `${marker}\n${hook}`
      );
    }
    return config;
  });
};
